create table if not exists public.deepwatch_reviews(id uuid primary key default gen_random_uuid(),video_id text not null check(video_id ~ '^[A-Za-z0-9_-]{11}$'),user_id uuid not null references auth.users(id) on delete cascade,rating smallint not null check(rating between 1 and 5),body text not null check(char_length(trim(body)) between 1 and 3000),created_at timestamptz not null default now(),unique(video_id,user_id));create index if not exists deepwatch_reviews_video_idx on public.deepwatch_reviews(video_id,created_at desc);alter table public.deepwatch_reviews enable row level security;create policy "Read DeepWatch reviews" on public.deepwatch_reviews for select using(true);create policy "Create own DeepWatch review" on public.deepwatch_reviews for insert to authenticated with check(auth.uid()=user_id);create policy "Edit own DeepWatch review" on public.deepwatch_reviews for update to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "Delete own DeepWatch review" on public.deepwatch_reviews for delete to authenticated using(auth.uid()=user_id);